const MACROS=[{id:"a",label:"Identita e Struttura",color:"#3b82f6",bg:"#dbeafe"},{id:"b",label:"Governance",color:"#7c3aed",bg:"#ede9fe"},{id:"c",label:"Organizzazione",color:"#0891b2",bg:"#cffafe"},{id:"d",label:"Compliance e Controlli",color:"#d97706",bg:"#fef3c7"},{id:"e",label:"Rapporti con la PA",color:"#e11d48",bg:"#fecdd3"},{id:"f",label:"Risk Management",color:"#dc2626",bg:"#fee2e2"},{id:"g",label:"Rapporti Esterni",color:"#059669",bg:"#d1fae5"},{id:"h",label:"Adeguati Assetti",color:"#7c3aed",bg:"#ede9fe"},{id:"i",label:"Documentazione",color:"#475569",bg:"#e2e8f0"},{id:"j",label:"Autovalutazione",color:"#ca8a04",bg:"#fef9c3"},{id:"k",label:"Owner Macro Aree",color:"#9333ea",bg:"#f3e8ff"}];
const TYPES=["text","textarea","select","multiselect","number"];
const SECTIONS=_R.map(s=>({id:s[0],macro:s[1],title:s[2],fields:s[3].map(f=>({id:f[0],label:f[1],type:TYPES[f[2]],required:!!f[3],...(f[4]?{options:f[4].split("|").filter(x=>x.trim())}:{}),...(f[5]?{help:f[5]}:{})}))}));
const initData={};SECTIONS.forEach(s=>s.fields.forEach(f=>{initData[f.id]="";}));
const F="'DM Sans','Inter',-apple-system,sans-serif";
const ts=()=>new Date().toLocaleString("it-IT",{day:"2-digit",month:"2-digit",year:"numeric",hour:"2-digit",minute:"2-digit"});
const uid=()=>Math.random().toString(36).substr(2,9);
const S=(bg,fg,x={})=>({padding:"9px 18px",fontSize:13,fontWeight:600,color:fg,background:bg,border:"none",borderRadius:10,cursor:"pointer",fontFamily:F,display:"flex",alignItems:"center",gap:6,...x});
const C=(x={})=>({background:"#fff",borderRadius:16,border:"1px solid #e2e8f0",boxShadow:"0 1px 3px rgba(0,0,0,.04)",...x});
const B=(c,bg)=>({display:"inline-block",padding:"3px 10px",fontSize:11,fontWeight:700,borderRadius:6,color:c,background:bg});

/* ============ FIELD COMPONENT ============ */
function Field({field,value,onChange,fieldNote,onNoteChange,naChecked,onNaChange,readOnly,adminNote,onAdminNoteChange,isAdmin}){
  const[fc,setFc]=useState(false);const[sh,setSh]=useState(false);const[sn,setSn]=useState(!!fieldNote);const[san,setSan]=useState(!!adminNote);
  const disabled=readOnly||naChecked;
  const st={width:"100%",padding:"10px 14px",fontSize:13.5,border:"1.5px solid "+(naChecked?"#e2e8f0":fc?"#6366f1":"#e2e8f0"),borderRadius:10,background:naChecked?"#f8fafc":disabled?"#f1f5f9":fc?"#fff":"#f8fafc",color:naChecked?"#94a3b8":"#1e293b",fontFamily:F,outline:"none",transition:"all .2s",boxSizing:"border-box",boxShadow:fc&&!naChecked?"0 0 0 3px rgba(99,102,241,.08)":"none",opacity:naChecked?.5:1};
  const h=disabled?{}:{onFocus:()=>setFc(true),onBlur:()=>setFc(false)};
  return(<div style={{marginBottom:18,position:"relative"}}>
    <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:6}}>
      <label style={{fontSize:12.5,fontWeight:600,color:naChecked?"#94a3b8":"#334155",fontFamily:F,flex:1,textDecoration:naChecked?"line-through":"none",opacity:naChecked?.5:1}}>{field.label}{field.required&&!naChecked&&<span style={{color:"#ef4444",marginLeft:2}}>*</span>}</label>
      {!readOnly&&<label title="Non Applicabile" style={{display:"flex",alignItems:"center",gap:3,padding:"2px 8px",fontSize:10,fontWeight:700,color:naChecked?"#ef4444":"#94a3b8",background:naChecked?"#fef2f2":"transparent",border:"1px solid "+(naChecked?"#fecaca":"#e2e8f0"),borderRadius:6,cursor:"pointer",letterSpacing:.5,transition:"all .2s",userSelect:"none"}}><input type="checkbox" checked={naChecked} onChange={e=>onNaChange(field.id,e.target.checked)} style={{width:12,height:12,accentColor:"#ef4444"}}/>N/A</label>}
      {!readOnly&&!naChecked&&<button onClick={()=>setSn(!sn)} title="Aggiungi nota" style={{display:"flex",padding:"3px 7px",background:sn||fieldNote?"#eef2ff":"transparent",border:"1px solid "+(sn||fieldNote?"#c7d2fe":"transparent"),borderRadius:6,cursor:"pointer",color:sn||fieldNote?"#6366f1":"#94a3b8",fontSize:13,transition:"all .2s"}}>Nota</button>}
      {isAdmin&&!naChecked&&<button onClick={()=>setSan(!san)} title="Nota consulente" style={{display:"flex",padding:"3px 7px",background:san||adminNote?"#fef3c7":"transparent",border:"1px solid "+(san||adminNote?"#fde68a":"transparent"),borderRadius:6,cursor:"pointer",color:san||adminNote?"#92400e":"#94a3b8",fontSize:12,transition:"all .2s"}}>Nota consulente</button>}
      {field.help&&<div style={{position:"relative"}}><button onClick={()=>setSh(!sh)} title="Info" style={{display:"flex",padding:"3px 7px",background:sh?"#eef2ff":"transparent",border:"1px solid "+(sh?"#c7d2fe":"transparent"),borderRadius:6,cursor:"pointer",color:sh?"#6366f1":"#94a3b8",fontSize:13,transition:"all .2s"}}>?</button>
        {sh&&<div style={{position:"absolute",right:0,top:28,zIndex:50,width:380,maxHeight:320,overflowY:"auto",padding:"14px 16px",background:"#fff",border:"1.5px solid #e2e8f0",borderRadius:12,boxShadow:"0 12px 32px rgba(0,0,0,.12)",fontSize:12,lineHeight:1.7,color:"#334155",fontFamily:F}}><div style={{fontWeight:700,color:"#6366f1",marginBottom:6,fontSize:11,textTransform:"uppercase",letterSpacing:.5}}>Informazioni</div><div style={{whiteSpace:"pre-wrap"}}>{field.help}</div><button onClick={()=>setSh(false)} style={{display:"block",marginTop:10,padding:"4px 12px",fontSize:11,color:"#6366f1",background:"#eef2ff",border:"none",borderRadius:6,cursor:"pointer",fontWeight:600}}>Chiudi</button></div>}
      </div>}
    </div>
    {naChecked?<div style={{padding:"10px 14px",background:"#fef2f2",borderRadius:10,border:"1px dashed #fecaca",fontSize:12,color:"#ef4444",fontWeight:500,fontFamily:F,textAlign:"center"}}>Campo contrassegnato come Non Applicabile</div>
    :field.type==="textarea"?<textarea value={value} onChange={disabled?undefined:e=>onChange(field.id,e.target.value)} rows={3} style={{...st,resize:"vertical",minHeight:72}} readOnly={disabled} {...h}/>
    :field.type==="select"?<select value={value} onChange={disabled?undefined:e=>onChange(field.id,e.target.value)} style={{...st,cursor:disabled?"default":"pointer"}} disabled={disabled} {...h}><option value="">— Selezionare —</option>{(field.options||[]).map(o=><option key={o} value={o}>{o}</option>)}</select>
    :field.type==="multiselect"?<div style={{display:"flex",flexWrap:"wrap",gap:6,padding:8,background:"#f8fafc",borderRadius:10,border:"1.5px solid #e2e8f0"}}>
      {(field.options||[]).map(o=>{const sel=(value||"").split("||").includes(o);return <button key={o} disabled={disabled} onClick={()=>{if(disabled)return;const cur=(value||"").split("||").filter(Boolean);const nv=sel?cur.filter(x=>x!==o):[...cur,o];onChange(field.id,nv.join("||"));}} style={{padding:"5px 12px",fontSize:12,fontWeight:sel?600:400,color:sel?"#6366f1":"#64748b",background:sel?"#eef2ff":"#fff",border:"1.5px solid "+(sel?"#c7d2fe":"#e2e8f0"),borderRadius:8,cursor:disabled?"default":"pointer",transition:"all .15s",fontFamily:F}}>{o}</button>})}
    </div>
    :field.type==="number"?<input type="number" value={value} onChange={disabled?undefined:e=>onChange(field.id,e.target.value)} style={st} readOnly={disabled} {...h}/>
    :<input type="text" value={value} onChange={disabled?undefined:e=>onChange(field.id,e.target.value)} style={st} readOnly={disabled} {...h}/>}
    {sn&&!readOnly&&!naChecked&&<textarea value={fieldNote||""} onChange={e=>onNoteChange(field.id,e.target.value)} rows={2} placeholder="Nota sul campo..." style={{width:"100%",marginTop:6,padding:"8px 12px",fontSize:12,border:"1.5px solid #c7d2fe",borderRadius:8,background:"#eef2ff",color:"#312e81",fontFamily:F,outline:"none",resize:"vertical",boxSizing:"border-box"}}/>}
    {san&&isAdmin&&!naChecked&&<div style={{marginTop:6,position:"relative"}}><textarea value={adminNote||""} onChange={e=>onAdminNoteChange(field.id,e.target.value)} rows={2} placeholder="Nota del consulente (non modificabile dal cliente)..." style={{width:"100%",padding:"8px 12px",paddingRight:36,fontSize:12,border:"1.5px solid #fde68a",borderRadius:8,background:"#fefce8",color:"#713f12",fontFamily:F,outline:"none",resize:"vertical",boxSizing:"border-box"}}/>{adminNote&&<button onClick={()=>{onAdminNoteChange(field.id,"");setSan(false);}} title="Elimina nota" style={{position:"absolute",top:6,right:8,padding:"2px 6px",fontSize:11,color:"#ef4444",background:"#fef2f2",border:"1px solid #fecaca",borderRadius:4,cursor:"pointer",fontFamily:F,fontWeight:600,lineHeight:1}}>x</button>}</div>}
    {readOnly&&fieldNote&&!naChecked&&<div style={{marginTop:4,padding:"6px 10px",fontSize:11,background:"#eef2ff",borderRadius:6,color:"#4338ca",fontFamily:F}}>Nota cliente: {fieldNote}</div>}
    {!isAdmin&&adminNote&&!naChecked&&<div style={{marginTop:4,padding:"6px 10px",fontSize:11,background:"#fefce8",borderRadius:6,color:"#92400e",fontFamily:F,borderLeft:"3px solid #f59e0b"}}>Nota consulente: {adminNote}</div>}
    {isAdmin&&!san&&adminNote&&!naChecked&&<div style={{marginTop:4,padding:"6px 10px",fontSize:11,background:"#fefce8",borderRadius:6,color:"#92400e",fontFamily:F,borderLeft:"3px solid #f59e0b"}}>Nota consulente: {adminNote}</div>}
  </div>);
}

/* ============ PDF GENERATION ============ */
function genPDF(data,sn,fn,naFields,adminNotes,mode,inclAN){
  const excludeNA=mode==="excludeNA";
  const now=new Date().toLocaleString("it-IT");const r=data.ragione_sociale||"Societa";
  let h='<!DOCTYPE html><html><head><meta charset="utf-8"><title>Pre-Assessment v13</title><style>@page{size:A4;margin:18mm 16mm}*{box-sizing:border-box;margin:0;padding:0}body{font-family:Segoe UI,Arial,sans-serif;font-size:11px;color:#1e293b;line-height:1.5}.cv{page-break-after:always;display:flex;flex-direction:column;justify-content:center;align-items:center;height:90vh;text-align:center}.cv h1{font-size:28px;color:#0f172a;margin-bottom:4px}.cv h2{font-size:16px;color:#6366f1;font-weight:600;margin-bottom:30px}.cv .co{font-size:22px;color:#334155;margin-bottom:6px}.cv .dt{font-size:13px;color:#94a3b8}.ma{page-break-before:always}.ma h2{font-size:16px;color:#fff;background:#0f172a;padding:10px 16px;border-radius:6px;margin-bottom:14px}.se{margin-bottom:20px}.se h3{font-size:13px;color:#6366f1;border-bottom:2px solid #e2e8f0;padding-bottom:4px;margin-bottom:10px}.fd{display:flex;padding:4px 0;border-bottom:1px solid #f1f5f9}.fl{width:45%;font-weight:600;color:#334155;font-size:10.5px}.fv{width:55%;font-size:10.5px}.fn{font-size:9.5px;color:#4338ca;font-style:italic;margin-top:2px}.an{font-size:9.5px;color:#92400e;margin-top:2px;border-left:2px solid #f59e0b;padding-left:6px}.em{color:#cbd5e1;font-style:italic}.na-tag{color:#ef4444;font-style:italic;font-size:9.5px}.ns{margin-top:8px;padding:8px 12px;background:#fefce8;border:1px solid #fef08a;border-radius:6px;font-size:10px;color:#713f12}.ft{text-align:center;font-size:9px;color:#94a3b8;margin-top:30px;border-top:1px solid #e2e8f0;padding-top:8px}</style></head><body>';
  h+='<div class="cv"><h1>GOVERNANCE</h1><h2>PRE-ASSESSMENT TOOL v13</h2><div class="co">'+r+'</div><div class="dt">Report generato il '+now+'</div><div style="margin-top:40px;font-size:12px;color:#94a3b8">11 Macro Aree | 53 Sezioni | 556 Campi'+(excludeNA?' | Campi N/A esclusi':'')+(inclAN?' | Note consulente incluse':'')+'</div></div>';
  MACROS.forEach(m=>{const ss=SECTIONS.filter(s=>s.macro===m.id);if(!ss.length)return;h+='<div class="ma"><h2>'+m.label+'</h2>';ss.forEach(s=>{h+='<div class="se"><h3>'+s.title+'</h3>';s.fields.forEach(f=>{const isNA=!!naFields[f.id];if(excludeNA&&isNA)return;const v=data[f.id];const n=fn[f.id];const an=adminNotes[f.id];h+='<div class="fd"><div class="fl">'+f.label+(f.required?' *':'')+'</div><div class="fv">';if(isNA){h+='<span class="na-tag">N/A</span>';}else{h+=(v?(v.includes("||")?v.split("||").join(", "):v).replace(/\n/g,'<br>'):'<span class="em">\u2014</span>');}if(n&&!isNA)h+='<div class="fn">Nota: '+n+'</div>';if(inclAN&&an&&!isNA)h+='<div class="an">Consulente: '+an+'</div>';h+='</div></div>';});if(sn[s.id])h+='<div class="ns"><strong>Note sezione:</strong> '+sn[s.id]+'</div>';h+='</div>';});h+='</div>';});
  const naCount=Object.values(naFields).filter(Boolean).length;
  h+='<div class="ft">Governance Pre-Assessment Tool v13 | Riservato'+(excludeNA?' | Campi N/A esclusi: '+naCount:' | Campi N/A inclusi: '+naCount)+'</div></body></html>';
  const w=window.open("","_blank");if(w){w.document.write(h);w.document.close();setTimeout(()=>w.print(),500);}
}

/* ============ CHAT PANEL ============ */
function ChatPanel({messages,onSend,myId,other}){
  const[msg,setMsg]=useState("");const ref=useRef(null);
  useEffect(()=>{ref.current?.scrollIntoView({behavior:"smooth"});},[messages]);
  const go=()=>{if(msg.trim()){onSend(msg.trim());setMsg("");}};
  return(<div style={{display:"flex",flexDirection:"column",height:"100%"}}>
    <div style={{padding:"16px 20px",borderBottom:"1px solid #e8ecf1",fontSize:14,fontWeight:700,color:"#0f172a",fontFamily:F,background:"#fafbfc"}}>Chat con {other}</div>
    <div style={{flex:1,overflowY:"auto",padding:16}}>
      {messages.length===0&&<div style={{textAlign:"center",padding:40,color:"#94a3b8",fontSize:13,fontFamily:F}}>Nessun messaggio.</div>}
      {messages.map((m,i)=>{const mine=m.from===myId;return(<div key={i} style={{display:"flex",justifyContent:mine?"flex-end":"flex-start",marginBottom:10}}><div style={{maxWidth:"75%",padding:"10px 14px",borderRadius:14,background:mine?"linear-gradient(135deg,#6366f1,#8b5cf6)":"#f1f5f9",color:mine?"#fff":"#1e293b",fontSize:13,fontFamily:F}}><div>{m.text}</div><div style={{fontSize:10,opacity:.7,marginTop:4,textAlign:"right"}}>{m.time}</div></div></div>);})}
      <div ref={ref}/></div>
    <div style={{padding:"12px 16px",borderTop:"1px solid #e8ecf1",display:"flex",gap:8,background:"#fafbfc"}}>
      <input value={msg} onChange={e=>setMsg(e.target.value)} placeholder="Scrivi..." onKeyDown={e=>e.key==="Enter"&&go()} style={{flex:1,padding:"10px 14px",fontSize:13,border:"1.5px solid #e2e8f0",borderRadius:10,background:"#fff",fontFamily:F,outline:"none",boxSizing:"border-box"}}/>
      <button onClick={go} style={S("linear-gradient(135deg,#6366f1,#8b5cf6)","#fff")}>Invia</button>
    </div></div>);
}

/* ============ TICKET PANEL ============ */
function TicketPanel({tickets,onNew,onReply,myId,isAdmin}){
  const[showN,setShowN]=useState(false);const[subj,setSubj]=useState("");const[body,setBody]=useState("");
  const[sel,setSel]=useState(null);const[reply,setReply]=useState("");
  const create=()=>{if(subj.trim()&&body.trim()){onNew(subj,body);setSubj("");setBody("");setShowN(false);}};
  const sendR=tid=>{if(reply.trim()){onReply(tid,reply);setReply("");}};
  const selected=sel!==null?tickets.find(t=>t.id===sel):null;
  return(<div style={{display:"flex",flexDirection:"column",height:"100%"}}>
    <div style={{padding:"16px 20px",borderBottom:"1px solid #e8ecf1",display:"flex",alignItems:"center",gap:8,background:"#fafbfc"}}>
      <span style={{flex:1,fontSize:14,fontWeight:700,color:"#0f172a",fontFamily:F}}>Ticket</span>
      {!isAdmin&&<button onClick={()=>setShowN(true)} style={S("#6366f1","#fff",{padding:"6px 14px",fontSize:12})}>+ Nuovo</button>}
    </div>
    {showN&&<div style={{padding:16,borderBottom:"1px solid #e8ecf1",background:"#fafbfc"}}>
      <input value={subj} onChange={e=>setSubj(e.target.value)} placeholder="Oggetto" style={{width:"100%",padding:"9px 12px",fontSize:13,border:"1.5px solid #e2e8f0",borderRadius:8,fontFamily:F,outline:"none",marginBottom:8,boxSizing:"border-box"}}/>
      <textarea value={body} onChange={e=>setBody(e.target.value)} rows={3} placeholder="Descrizione..." style={{width:"100%",padding:"9px 12px",fontSize:13,border:"1.5px solid #e2e8f0",borderRadius:8,fontFamily:F,outline:"none",resize:"vertical",boxSizing:"border-box",marginBottom:8}}/>
      <div style={{display:"flex",gap:8}}><button onClick={create} style={S("#6366f1","#fff",{padding:"7px 14px",fontSize:12})}>Invia</button><button onClick={()=>setShowN(false)} style={S("#fff","#64748b",{padding:"7px 14px",fontSize:12,border:"1px solid #e2e8f0"})}>Annulla</button></div>
    </div>}
    <div style={{flex:1,overflowY:"auto"}}>
      {tickets.length===0&&<div style={{textAlign:"center",padding:40,color:"#94a3b8",fontSize:13,fontFamily:F}}>Nessun ticket.</div>}
      {!selected&&tickets.map(t=>(<div key={t.id} onClick={()=>setSel(t.id)} style={{padding:"12px 18px",borderBottom:"1px solid #f1f5f9",cursor:"pointer"}}><div style={{display:"flex",alignItems:"center",gap:8,marginBottom:4}}><span style={{...B(t.status==="open"?"#f59e0b":"#10b981",t.status==="open"?"#fef3c7":"#d1fae5"),fontSize:10}}>{t.status==="open"?"Aperto":"Chiuso"}</span><span style={{fontSize:13,fontWeight:600,color:"#0f172a",fontFamily:F}}>{t.subject}</span></div><div style={{fontSize:11,color:"#94a3b8",fontFamily:F}}>{t.time}</div></div>))}
      {selected&&<div style={{padding:18}}>
        <button onClick={()=>setSel(null)} style={{...S("#f8fafc","#334155",{padding:"5px 10px",fontSize:12,border:"1px solid #e2e8f0",marginBottom:12})}}>Indietro</button>
        <h3 style={{margin:"0 0 8px",fontSize:15,fontWeight:700,color:"#0f172a",fontFamily:F}}>{selected.subject}</h3>
        <div style={{padding:"10px 14px",background:"#f8fafc",borderRadius:10,marginBottom:12,fontSize:13,color:"#334155",fontFamily:F}}>{selected.body}<div style={{fontSize:10,color:"#94a3b8",marginTop:6}}>{selected.time}</div></div>
        {(selected.replies||[]).map((r,i)=>(<div key={i} style={{padding:"10px 14px",background:r.from===myId?"#eef2ff":"#f8fafc",borderRadius:10,marginBottom:8,fontSize:13,fontFamily:F,borderLeft:"3px solid "+(r.from===myId?"#6366f1":"#e2e8f0")}}><div style={{fontSize:11,fontWeight:600,color:"#64748b",marginBottom:4}}>{r.fromName}</div>{r.text}<div style={{fontSize:10,color:"#94a3b8",marginTop:4}}>{r.time}</div></div>))}
        <div style={{display:"flex",gap:8,marginTop:12}}><input value={reply} onChange={e=>setReply(e.target.value)} placeholder="Rispondi..." onKeyDown={e=>e.key==="Enter"&&sendR(selected.id)} style={{flex:1,padding:"9px 12px",fontSize:13,border:"1.5px solid #e2e8f0",borderRadius:8,fontFamily:F,outline:"none",boxSizing:"border-box"}}/><button onClick={()=>sendR(selected.id)} style={S("#6366f1","#fff",{padding:"8px 14px"})}>Invia</button></div>
      </div>}
    </div></div>);
}

/* ============ ALERT PANEL ============ */
function AlertPanel({alerts,onNew,users,isAdmin}){
  const[showN,setShowN]=useState(false);const[target,setTarget]=useState("");const[text,setText]=useState("");const[pri,setPri]=useState("info");
  const create=()=>{if(text.trim()){onNew(target,text,pri);setText("");setTarget("");setShowN(false);}};
  const pc={info:["#6366f1","#eef2ff"],warning:["#f59e0b","#fef3c7"],urgent:["#ef4444","#fef2f2"]};
  return(<div style={{display:"flex",flexDirection:"column",height:"100%"}}>
    <div style={{padding:"16px 20px",borderBottom:"1px solid #e8ecf1",display:"flex",alignItems:"center",gap:8,background:"#fafbfc"}}>
      <span style={{flex:1,fontSize:14,fontWeight:700,color:"#0f172a",fontFamily:F}}>Alert</span>
      {isAdmin&&<button onClick={()=>setShowN(true)} style={S("#ef4444","#fff",{padding:"6px 14px",fontSize:12})}>+ Nuovo</button>}
    </div>
    {showN&&isAdmin&&<div style={{padding:16,borderBottom:"1px solid #e8ecf1",background:"#fafbfc"}}>
      <select value={target} onChange={e=>setTarget(e.target.value)} style={{width:"100%",padding:"9px 12px",fontSize:13,border:"1.5px solid #e2e8f0",borderRadius:8,fontFamily:F,outline:"none",marginBottom:8,boxSizing:"border-box"}}><option value="">Tutti</option>{users.map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select>
      <select value={pri} onChange={e=>setPri(e.target.value)} style={{width:"100%",padding:"9px 12px",fontSize:13,border:"1.5px solid #e2e8f0",borderRadius:8,fontFamily:F,outline:"none",marginBottom:8,boxSizing:"border-box"}}><option value="info">Info</option><option value="warning">Attenzione</option><option value="urgent">Urgente</option></select>
      <textarea value={text} onChange={e=>setText(e.target.value)} rows={2} placeholder="Testo..." style={{width:"100%",padding:"9px 12px",fontSize:13,border:"1.5px solid #e2e8f0",borderRadius:8,fontFamily:F,outline:"none",resize:"vertical",boxSizing:"border-box",marginBottom:8}}/>
      <div style={{display:"flex",gap:8}}><button onClick={create} style={S("#ef4444","#fff",{padding:"7px 14px",fontSize:12})}>Invia</button><button onClick={()=>setShowN(false)} style={S("#fff","#64748b",{padding:"7px 14px",fontSize:12,border:"1px solid #e2e8f0"})}>Annulla</button></div>
    </div>}
    <div style={{flex:1,overflowY:"auto",padding:12}}>
      {alerts.length===0&&<div style={{textAlign:"center",padding:40,color:"#94a3b8",fontSize:13,fontFamily:F}}>Nessun alert.</div>}
      {alerts.map(a=>{const[fg,bg]=pc[a.priority]||pc.info;return(<div key={a.id} style={{padding:"12px 14px",background:bg,borderRadius:12,marginBottom:8,borderLeft:"4px solid "+fg}}><div style={{display:"flex",alignItems:"center",gap:8,marginBottom:4}}><span style={{fontSize:10,fontWeight:700,color:fg}}>{a.priority==="urgent"?"URGENTE":a.priority==="warning"?"ATTENZIONE":"INFO"}</span><span style={{fontSize:10,color:"#94a3b8",fontFamily:F}}>{a.time}</span></div><div style={{fontSize:13,color:"#1e293b",fontFamily:F}}>{a.text}</div>{a.targetName&&<div style={{fontSize:11,color:"#64748b",marginTop:4}}>Dest.: {a.targetName}</div>}</div>);})}
    </div></div>);
}

/* ============ LOGIN PAGE ============ */
function LoginPage({onLogin}){
  const[email,setEmail]=useState("");const[pwd,setPwd]=useState("");const[err,setErr]=useState("");
  const creds=[
    {email:"superadmin@gov.it",pwd:"super",role:"superadmin",name:"System Admin",id:"sa1"},
    {email:"g.iorlano@studio.it",pwd:"admin",role:"admin",name:"Avv. Gerardo Iorlano",id:"admin1"},
    {email:"admin@alfa.it",pwd:"user",role:"user",name:"Alfa S.r.l.",id:"user1",adminId:"admin1"},
    {email:"cfo@beta.it",pwd:"user",role:"user",name:"Beta S.p.A.",id:"user2",adminId:"admin1"},
  ];
  const go=()=>{const u=creds.find(c=>c.email===email&&c.pwd===pwd);if(u)onLogin(u);else setErr("Credenziali non valide");};
  return(<div style={{fontFamily:F,minHeight:"100vh",display:"flex",alignItems:"center",justifyContent:"center",background:"linear-gradient(160deg,#0c1222 0%,#1a1f3a 40%,#2d1b4e 100%)"}}>
    <div style={{position:"absolute",inset:0,background:"radial-gradient(ellipse at 20% 50%,rgba(99,102,241,.08),transparent 60%),radial-gradient(ellipse at 80% 20%,rgba(139,92,246,.06),transparent 50%)"}}/>
    <div style={{width:440,position:"relative",...C({padding:"44px 40px",background:"rgba(255,255,255,.97)"})}}>
      <div style={{textAlign:"center",marginBottom:36}}>
        <div style={{width:64,height:64,borderRadius:18,background:"linear-gradient(135deg,#6366f1,#8b5cf6,#a78bfa)",display:"inline-flex",alignItems:"center",justifyContent:"center",fontSize:28,fontWeight:900,color:"#fff",fontFamily:F,marginBottom:18,boxShadow:"0 8px 32px rgba(99,102,241,.3)"}}>G</div>
        <h1 style={{margin:0,fontSize:26,fontWeight:900,color:"#0f172a",fontFamily:F,letterSpacing:-.5}}>GOVERNANCE</h1>
        <p style={{margin:"4px 0 0",fontSize:11,color:"#6366f1",fontWeight:700,letterSpacing:3,textTransform:"uppercase",fontFamily:F}}>Pre-Assessment Tool</p>
        <p style={{margin:"8px 0 0",fontSize:11,color:"#94a3b8",fontFamily:F}}>v13 — 11 Macro Aree | 53 Sezioni | 556 Campi</p>
      </div>
      <div style={{marginBottom:16}}><label style={{display:"block",fontSize:12,fontWeight:600,color:"#334155",marginBottom:5,fontFamily:F}}>Email</label><input type="email" value={email} onChange={e=>{setEmail(e.target.value);setErr("");}} placeholder="email@esempio.it" style={{width:"100%",padding:"12px 14px",fontSize:14,border:"1.5px solid #e2e8f0",borderRadius:10,background:"#f8fafc",fontFamily:F,outline:"none",boxSizing:"border-box"}} onKeyDown={e=>e.key==="Enter"&&go()}/></div>
      <div style={{marginBottom:22}}><label style={{display:"block",fontSize:12,fontWeight:600,color:"#334155",marginBottom:5,fontFamily:F}}>Password</label><input type="password" value={pwd} onChange={e=>{setPwd(e.target.value);setErr("");}} placeholder="••••••" style={{width:"100%",padding:"12px 14px",fontSize:14,border:"1.5px solid #e2e8f0",borderRadius:10,background:"#f8fafc",fontFamily:F,outline:"none",boxSizing:"border-box"}} onKeyDown={e=>e.key==="Enter"&&go()}/></div>
      {err&&<div style={{padding:"8px 12px",marginBottom:14,fontSize:12,color:"#dc2626",background:"#fef2f2",borderRadius:8,fontFamily:F}}>{err}</div>}
      <button onClick={go} style={{...S("linear-gradient(135deg,#6366f1,#8b5cf6)","#fff",{width:"100%",padding:"13px",fontSize:14,justifyContent:"center",borderRadius:12,boxShadow:"0 4px 16px rgba(99,102,241,.25)"})}}>Accedi</button>
      <div style={{marginTop:28,padding:"16px 18px",background:"#f8fafc",borderRadius:12,border:"1px solid #e8ecf1"}}>
        <p style={{margin:"0 0 10px",fontSize:11,fontWeight:700,color:"#64748b",fontFamily:F,letterSpacing:1}}>CREDENZIALI DEMO</p>
        {[{r:"SuperAdmin",e:"superadmin@gov.it",p:"super"},{r:"Consulente",e:"g.iorlano@studio.it",p:"admin"},{r:"Cliente",e:"admin@alfa.it",p:"user"}].map(c=>(<div key={c.e} style={{display:"flex",alignItems:"center",gap:8,marginBottom:5,fontSize:11,fontFamily:F,cursor:"pointer",padding:"4px 6px",borderRadius:6}} onClick={()=>{setEmail(c.e);setPwd(c.p);setErr("");}}>
          <span style={{...B("#6366f1","#eef2ff"),fontSize:10,minWidth:76,textAlign:"center"}}>{c.r}</span><span style={{color:"#334155"}}>{c.e}</span><span style={{color:"#94a3b8"}}>/ {c.p}</span></div>))}
      </div>
    </div></div>);
}

/* ============ MAIN APP ============ */
export default function App(){
  const[auth,setAuth]=useState(null);
  const[admins,setAdmins]=useState([{id:"admin1",name:"Avv. Gerardo Iorlano",email:"g.iorlano@studio.it",maxSub:5,active:true}]);
  const[users,setUsers]=useState([{id:"user1",adminId:"admin1",name:"Alfa S.r.l.",email:"admin@alfa.it",active:true},{id:"user2",adminId:"admin1",name:"Beta S.p.A.",email:"cfo@beta.it",active:true}]);
  const[assessments,setAssessments]=useState({user1:{...initData},user2:{...initData}});
  const[allFN,setAllFN]=useState({});const[allSN,setAllSN]=useState({});const[allNA,setAllNA]=useState({});const[allAN,setAllAN]=useState({});
  const[macroValidations,setMacroValidations]=useState({});
  const[chats,setChats]=useState({});const[tickets,setTickets]=useState({});const[alerts,setAlerts]=useState({});
  const[view,setView]=useState("dashboard");const[search,setSearch]=useState("");const[expandedMacro,setExpandedMacro]=useState(null);
  const[sidebarOpen,setSidebarOpen]=useState(true);const[showExport,setShowExport]=useState(false);const[exportMode,setExportMode]=useState("excludeNA");const[exportAdminNotes,setExportAdminNotes]=useState(true);
  const[selectedUser,setSelectedUser]=useState(null);const[panel,setPanel]=useState(null);
  const[dashFilter,setDashFilter]=useState("all");
  const[saForm,setSaForm]=useState({name:"",email:"",maxSub:3});

  const curId=auth?.id;const curAdm=auth?.role==="admin"?auth.id:auth?.adminId;
  const myUsers=users.filter(u=>u.adminId===curAdm);
  const actUid=auth?.role==="user"?auth.id:selectedUser;
  const data=actUid?(assessments[actUid]||initData):initData;
  const fieldNotes=actUid?(allFN[actUid]||{}):{};const sectionNotes=actUid?(allSN[actUid]||{}):{};const naFields=actUid?(allNA[actUid]||{}):{};const adminNotes=actUid?(allAN[actUid]||{}):{};
  const validations=actUid?(macroValidations[actUid]||{}):{};
  const readOnly=auth?.role==="admin";const isAdmin=auth?.role==="admin";const showAss=auth?.role==="user"||(auth?.role==="admin"&&selectedUser);
  const chatKey=uid2=>curAdm+"-"+uid2;
  const getChats=uid2=>chats[chatKey(uid2)]||[];
  const getTickets=uid2=>tickets[uid2]||[];
  const getAlerts=uid2=>{const all=alerts[curAdm]||[];return auth?.role==="user"?all.filter(a=>!a.targetId||a.targetId===uid2):all;};

  const handleChange=useCallback((fid,val)=>{if(!actUid||readOnly)return;setAssessments(p=>({...p,[actUid]:{...(p[actUid]||initData),[fid]:val}}));},[actUid,readOnly]);
  const handleFN=useCallback((fid,val)=>{if(!actUid||readOnly)return;setAllFN(p=>({...p,[actUid]:{...(p[actUid]||{}),[fid]:val}}));},[actUid,readOnly]);
  const handleSN=useCallback((sid,val)=>{if(!actUid||readOnly)return;setAllSN(p=>({...p,[actUid]:{...(p[actUid]||{}),[sid]:val}}));},[actUid,readOnly]);
  const handleNA=useCallback((fid,val)=>{if(!actUid||readOnly)return;setAllNA(p=>({...p,[actUid]:{...(p[actUid]||{}),[fid]:val}}));if(val)setAssessments(p=>({...p,[actUid]:{...(p[actUid]||initData),[fid]:""}}));},[actUid,readOnly]);
  const handleAN=useCallback((fid,val)=>{if(!actUid||!isAdmin)return;setAllAN(p=>({...p,[actUid]:{...(p[actUid]||{}),[fid]:val}}));},[actUid,isAdmin]);
  const handleValidateMacro=useCallback((macroId)=>{if(!actUid)return;setMacroValidations(p=>({...p,[actUid]:{...(p[actUid]||{}),[macroId]:{by:auth.name,at:ts(),userId:auth.id}}}));},[actUid,auth]);
  const handleRevokeValidation=useCallback((macroId)=>{if(!actUid)return;setMacroValidations(p=>{const cur={...(p[actUid]||{})};delete cur[macroId];return{...p,[actUid]:cur};});},[actUid]);

  const sendChat=msg=>{const uid2=auth?.role==="user"?auth.id:selectedUser;if(!uid2)return;const k=chatKey(uid2);setChats(p=>({...p,[k]:[...(p[k]||[]),{from:curId,text:msg,time:ts()}]}));};
  const createTicket=(s2,b2)=>{setTickets(p=>({...p,[auth.id]:[...(p[auth.id]||[]),{id:uid(),from:auth.id,subject:s2,body:b2,time:ts(),status:"open",replies:[]}]}));};
  const replyTicket=(tid,text)=>{const u=auth?.role==="user"?auth.id:selectedUser;setTickets(p=>{const l=[...(p[u]||[])];const i=l.findIndex(t=>t.id===tid);if(i>=0)l[i]={...l[i],replies:[...(l[i].replies||[]),{from:curId,fromName:auth.name,text,time:ts()}]};return{...p,[u]:l};});};
  const createAlert=(tid,text,pri)=>{const tn=tid?users.find(u=>u.id===tid)?.name||"":"Tutti";setAlerts(p=>({...p,[auth.id]:[...(p[auth.id]||[]),{id:uid(),targetId:tid,targetName:tn,text,priority:pri,time:ts()}]}));};

  const dlFile=(content,name,type)=>{const b=new Blob([content],{type});const u=URL.createObjectURL(b);const a=document.createElement("a");a.href=u;a.download=name;a.click();URL.revokeObjectURL(u);};
  const exportJSON=()=>{const excl=exportMode==="excludeNA";const inclAN=exportAdminNotes;const exp={tool:"Governance Pre-Assessment Tool v13",mode:excl?"Escludi N/A":"Tutto",noteConsulente:inclAN?"incluse":"escluse",sezioni:SECTIONS.map(s=>({id:s.id,titolo:s.title,risposte:Object.fromEntries(s.fields.filter(f=>!(excl&&naFields[f.id])).map(f=>{const o={label:f.label,valore:naFields[f.id]?"N/A":(data[f.id]||"")};if(inclAN&&adminNotes[f.id]&&!naFields[f.id])o.notaConsulente=adminNotes[f.id];return[f.id,o];}))}))};dlFile(JSON.stringify(exp,null,2),"assessment_"+new Date().toISOString().slice(0,10)+".json","application/json");};
  const esc=v=>String(v||"").replace(/"/g,'""').replace(/\n/g," ");
  const exportCSV=()=>{const excl=exportMode==="excludeNA";const inclAN=exportAdminNotes;const hdr=["Macro Area;Sezione;Campo;Obbligatorio;Valore;Nota"+(inclAN?";Nota Consulente":"")];const rows=[...hdr];SECTIONS.forEach(s=>{const ml=MACROS.find(x=>x.id===s.macro)?.label||"";s.fields.forEach(f=>{if(excl&&naFields[f.id])return;const isNA=!!naFields[f.id];const v=isNA?"N/A":(data[f.id]||"").includes("||")?(data[f.id]||"").split("||").join(", "):data[f.id];let row='"'+esc(ml)+'";"'+esc(s.title)+'";"'+esc(f.label)+'";"'+(f.required?"Si":"No")+'";"'+esc(v)+'";"'+esc(isNA?"":fieldNotes[f.id])+'"';if(inclAN)row+=';"'+esc(isNA?"":adminNotes[f.id])+'"';rows.push(row);});});dlFile("\uFEFF"+rows.join("\n"),"assessment_"+new Date().toISOString().slice(0,10)+".csv","text/csv;charset=utf-8;");};

  const totalReq=useMemo(()=>SECTIONS.reduce((a,s)=>a+s.fields.filter(f=>f.required&&!naFields[f.id]).length,0),[naFields]);
  const totalFilled=useMemo(()=>SECTIONS.reduce((a,s)=>a+s.fields.filter(f=>f.required&&!naFields[f.id]&&data[f.id]?.trim?.()).length,0),[data,naFields]);
  const totalFields=useMemo(()=>SECTIONS.reduce((a,s)=>a+s.fields.length,0),[]);
  const totalNA=useMemo(()=>Object.values(naFields).filter(Boolean).length,[naFields]);
  const pct=totalReq>0?Math.round((totalFilled/totalReq)*100):0;
  const sDone=s=>s.fields.filter(f=>f.required&&!naFields[f.id]&&data[f.id]?.trim?.()).length;
  const sTotal=s=>s.fields.filter(f=>f.required&&!naFields[f.id]).length;
  const sNA=s=>s.fields.filter(f=>naFields[f.id]).length;

  const fieldMatchesFilter=(f)=>{
    if(dashFilter==="all")return true;
    if(dashFilter==="completed")return !naFields[f.id]&&data[f.id]?.trim?.();
    if(dashFilter==="todo")return !naFields[f.id]&&!data[f.id]?.trim?.();
    if(dashFilter==="na")return !!naFields[f.id];
    return true;
  };

  const goToSection=useCallback((idx)=>{if(idx==="dashboard"){setView("dashboard");return;}setView(idx);const s=SECTIONS[idx];if(s)setExpandedMacro(s.macro);},[]);

  const filtered=useMemo(()=>{
    let sects=SECTIONS;
    if(search.trim()){const t=search.toLowerCase();sects=sects.filter(s=>s.title.toLowerCase().includes(t)||s.fields.some(f=>f.label.toLowerCase().includes(t)));}
    return sects;
  },[search]);
  const grouped=useMemo(()=>MACROS.map(m=>({...m,sections:filtered.filter(s=>s.macro===m.id)})).filter(g=>g.sections.length>0),[filtered]);

  if(!auth)return <LoginPage onLogin={setAuth}/>;

  /* ============ SUPERADMIN ============ */
  if(auth.role==="superadmin"){return(
    <div style={{fontFamily:F,minHeight:"100vh",background:"#f0f2f7",padding:24}}>
      <div style={{maxWidth:1000,margin:"0 auto"}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:24}}>
          <div><h1 style={{margin:0,fontSize:24,fontWeight:800,color:"#0f172a",fontFamily:F}}>Pannello SuperAdmin</h1><p style={{margin:"4px 0 0",fontSize:13,color:"#64748b",fontFamily:F}}>Gestione licenziatari</p></div>
          <button onClick={()=>setAuth(null)} style={S("#fff","#64748b",{border:"1px solid #e2e8f0"})}>Esci</button>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:14,marginBottom:24}}>
          {[{l:"Licenziatari",v:admins.length},{l:"Max Sublicenze",v:admins.reduce((a,x)=>a+x.maxSub,0)},{l:"Sublicenze Attive",v:users.length}].map((c,i)=>(<div key={i} style={C({padding:"20px 18px"})}><div style={{fontSize:12,fontWeight:600,color:"#64748b",fontFamily:F}}>{c.l}</div><div style={{fontSize:30,fontWeight:800,color:"#0f172a",fontFamily:F,margin:"6px 0"}}>{c.v}</div></div>))}
        </div>
        <div style={{...C({padding:"20px 22px",marginBottom:24})}}>
          <h3 style={{margin:"0 0 14px",fontSize:15,fontWeight:700,fontFamily:F}}>Nuovo Licenziatario</h3>
          <div style={{display:"flex",gap:12,flexWrap:"wrap"}}>
            <input value={saForm.name} onChange={e=>setSaForm(p=>({...p,name:e.target.value}))} placeholder="Nome / Studio" style={{flex:2,minWidth:200,padding:"10px 14px",fontSize:13,border:"1.5px solid #e2e8f0",borderRadius:10,fontFamily:F,outline:"none",boxSizing:"border-box"}}/>
            <input value={saForm.email} onChange={e=>setSaForm(p=>({...p,email:e.target.value}))} placeholder="Email" style={{flex:2,minWidth:200,padding:"10px 14px",fontSize:13,border:"1.5px solid #e2e8f0",borderRadius:10,fontFamily:F,outline:"none",boxSizing:"border-box"}}/>
            <input type="number" value={saForm.maxSub} onChange={e=>setSaForm(p=>({...p,maxSub:parseInt(e.target.value)||1}))} min={1} style={{width:80,padding:"10px 14px",fontSize:13,border:"1.5px solid #e2e8f0",borderRadius:10,fontFamily:F,outline:"none",textAlign:"center",boxSizing:"border-box"}}/>
            <button onClick={()=>{if(saForm.name&&saForm.email){setAdmins(p=>[...p,{id:uid(),name:saForm.name,email:saForm.email,maxSub:saForm.maxSub,active:true}]);setSaForm({name:"",email:"",maxSub:3});}}} style={S("#6366f1","#fff")}>+ Aggiungi</button>
          </div>
        </div>
        <div style={C({overflow:"hidden"})}>
          <table style={{width:"100%",borderCollapse:"collapse",fontFamily:F}}>
            <thead><tr style={{borderBottom:"1px solid #f1f5f9"}}>{["LICENZIATARIO","EMAIL","MAX","ATTIVE","STATO"].map(h=><th key={h} style={{padding:"10px 16px",fontSize:10.5,fontWeight:700,color:"#94a3b8",textTransform:"uppercase",letterSpacing:1,textAlign:"left"}}>{h}</th>)}</tr></thead>
            <tbody>{admins.map(a=>{const used=users.filter(u=>u.adminId===a.id).length;return(<tr key={a.id} style={{borderBottom:"1px solid #f8fafc"}}><td style={{padding:"12px 16px",fontSize:13,fontWeight:600}}>{a.name}</td><td style={{padding:"12px 16px",fontSize:13,color:"#64748b"}}>{a.email}</td><td style={{padding:"12px 16px",fontSize:13,textAlign:"center"}}>{a.maxSub}</td><td style={{padding:"12px 16px",fontSize:13,fontWeight:600,textAlign:"center"}}>{used}</td><td style={{padding:"12px 16px"}}><span style={B(a.active?"#065f46":"#94a3b8",a.active?"#d1fae5":"#f1f5f9")}>{a.active?"Attivo":"Sospeso"}</span></td></tr>);})}</tbody>
          </table>
        </div>
      </div></div>);
  }

  /* ============ SECTION VIEW ============ */
  const activeSection=typeof view==="number"?SECTIONS[view]:null;
  const activeMacro=activeSection?MACROS.find(m=>m.id===activeSection.macro):null;
  const otherName=auth.role==="user"?(admins.find(a=>a.id===auth.adminId)?.name||"Consulente"):(users.find(u=>u.id===selectedUser)?.name||"Cliente");

  /* ============ DASHBOARD VIEW ============ */
  const DashView=()=>{
    if(!showAss&&auth.role==="admin")return(<div style={{textAlign:"center",padding:60}}><h2 style={{margin:"0 0 8px",fontSize:20,fontWeight:700,fontFamily:F}}>Seleziona un cliente</h2><p style={{fontSize:14,color:"#64748b",fontFamily:F}}>Scegli dalla sidebar per iniziare.</p></div>);
    const compSec=SECTIONS.filter(s=>{const t=sTotal(s);return t>0&&sDone(s)===t;}).length;
    const clientName=auth.role==="user"?auth.name:users.find(u=>u.id===selectedUser)?.name||"";
    const validatedCount=Object.keys(validations).length;
    return(<div>
      <div style={{background:"linear-gradient(135deg,#0f172a 0%,#1e293b 50%,#334155 100%)",borderRadius:20,padding:"32px 34px",marginBottom:22,color:"#fff",position:"relative",overflow:"hidden"}}>
        <div style={{position:"absolute",top:-40,right:-40,width:200,height:200,borderRadius:"50%",background:"radial-gradient(circle,rgba(99,102,241,.15),transparent 70%)"}}/>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",position:"relative"}}>
          <div><h2 style={{margin:0,fontSize:24,fontWeight:900,fontFamily:F,letterSpacing:-.3}}>{clientName}</h2><p style={{margin:"6px 0 0",fontSize:13,opacity:.7,fontFamily:F}}>{readOnly?"Sola lettura":"Compilazione"} — 11 macro aree, 53 sezioni, 556 campi</p></div>
          <div style={{textAlign:"right"}}><div style={{fontSize:48,fontWeight:900,fontFamily:F,lineHeight:1,background:"linear-gradient(135deg,#a78bfa,#6366f1)",WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent"}}>{pct}%</div><div style={{fontSize:11,opacity:.6,marginTop:2}}>completamento</div></div>
        </div>
        <div style={{marginTop:20,height:6,background:"rgba(255,255,255,.1)",borderRadius:99}}><div style={{height:"100%",width:pct+"%",background:"linear-gradient(90deg,#6366f1,#a78bfa)",borderRadius:99,transition:"width .6s"}}/></div>
      </div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(5,1fr)",gap:12,marginBottom:22}}>
        {[{l:"MACRO AREE",v:11,s:"tematiche"},{l:"SEZIONI",v:SECTIONS.length,s:compSec+" completate"},{l:"CAMPI",v:totalFields,s:totalReq+" obbligatori"},{l:"COMPILATI",v:totalFilled,s:"su "+totalReq+" obb."},{l:"N/A",v:totalNA,s:"esclusi"}].map((c,i)=>(<div key={i} style={C({padding:"16px 14px"})}><div style={{fontSize:10,fontWeight:700,color:"#64748b",fontFamily:F,letterSpacing:.5}}>{c.l}</div><div style={{fontSize:26,fontWeight:800,color:"#0f172a",fontFamily:F,margin:"4px 0 2px"}}>{c.v}</div><div style={{fontSize:10,color:"#94a3b8",fontFamily:F}}>{c.s}</div></div>))}
      </div>
      {/* FILTER BAR */}
      <div style={{...C({padding:"12px 18px",marginBottom:18}),display:"flex",alignItems:"center",gap:10}}>
        <span style={{fontSize:12,fontWeight:700,color:"#334155",fontFamily:F,marginRight:4}}>Filtra campi:</span>
        {[["all","Tutti"],["completed","Completati"],["todo","Da completare"],["na","N/A"]].map(([k,l])=>(<button key={k} onClick={()=>setDashFilter(k)} style={{padding:"5px 14px",fontSize:12,fontWeight:dashFilter===k?700:500,color:dashFilter===k?"#fff":k==="na"?"#ef4444":"#64748b",background:dashFilter===k?(k==="na"?"#ef4444":"#6366f1"):k==="na"?"#fef2f2":"#f8fafc",border:"1.5px solid "+(dashFilter===k?"transparent":"#e2e8f0"),borderRadius:8,cursor:"pointer",fontFamily:F,transition:"all .15s"}}>{l}</button>))}
        {dashFilter!=="all"&&<span style={{fontSize:11,color:"#94a3b8",fontFamily:F,marginLeft:8}}>
          {dashFilter==="completed"?totalFilled+" campi":dashFilter==="todo"?(totalReq-totalFilled)+" campi":totalNA+" campi"}
        </span>}
      </div>
      {/* MACRO AREA TABLE */}
      <div style={{...C({overflow:"hidden",marginBottom:22})}}>
        <div style={{padding:"16px 22px 12px",borderBottom:"1px solid #f1f5f9",display:"flex",alignItems:"center",justifyContent:"space-between"}}><h3 style={{margin:0,fontSize:15,fontWeight:700,fontFamily:F}}>Stato per Macro Area</h3>{validatedCount>0&&<span style={{...B("#059669","#d1fae5"),fontSize:10}}>{validatedCount}/{MACROS.length-1} validate</span>}</div>
        <table style={{width:"100%",borderCollapse:"collapse",fontFamily:F}}>
          <thead><tr style={{borderBottom:"1px solid #f1f5f9"}}>{["MACRO AREA","SEZ.","OBB.","COMP.","N/A","%","VALIDAZIONE"].map(h=><th key={h} style={{padding:"8px 14px",fontSize:10,fontWeight:700,color:"#94a3b8",textTransform:"uppercase",letterSpacing:1,textAlign:"left"}}>{h}</th>)}</tr></thead>
          <tbody>{MACROS.filter(m=>m.id!=="k").map(m=>{const sects=SECTIONS.filter(s=>s.macro===m.id);const r=sects.reduce((a,s)=>a+sTotal(s),0);const d=sects.reduce((a,s)=>a+sDone(s),0);const n=sects.reduce((a,s)=>a+sNA(s),0);const p2=r>0?Math.round((d/r)*100):0;const v=validations[m.id];return(<tr key={m.id} style={{borderBottom:"1px solid #f8fafc"}}><td style={{padding:"10px 14px",fontSize:13,fontWeight:600}}>{m.id.toUpperCase()}. {m.label}</td><td style={{padding:"10px 14px",fontSize:13,color:"#64748b",textAlign:"center"}}>{sects.length}</td><td style={{padding:"10px 14px",fontSize:13,textAlign:"center"}}>{r}</td><td style={{padding:"10px 14px",fontSize:13,fontWeight:600,textAlign:"center"}}>{d}</td><td style={{padding:"10px 14px",fontSize:13,textAlign:"center",color:n>0?"#ef4444":"#94a3b8"}}>{n>0?n:"—"}</td><td style={{padding:"10px 14px",minWidth:110}}><div style={{display:"flex",alignItems:"center",gap:6}}><div style={{flex:1,height:5,background:"#e8ecf1",borderRadius:99}}><div style={{height:"100%",width:p2+"%",background:p2===100?"#10b981":m.color,borderRadius:99,transition:"width .4s"}}/></div><span style={{fontSize:11,fontWeight:700,color:"#64748b",minWidth:28}}>{p2}%</span></div></td><td style={{padding:"10px 14px"}}>{v?<div style={{display:"flex",alignItems:"center",gap:6}}><span style={{...B("#059669","#d1fae5"),fontSize:10}}>Validata</span><span style={{fontSize:9,color:"#94a3b8"}}>{v.at}</span>{!readOnly&&<button onClick={()=>handleRevokeValidation(m.id)} style={{padding:"2px 6px",fontSize:9,color:"#ef4444",background:"#fef2f2",border:"1px solid #fecaca",borderRadius:4,cursor:"pointer",fontFamily:F}}>Revoca</button>}</div>:<div>{!readOnly&&p2===100&&<button onClick={()=>handleValidateMacro(m.id)} style={{padding:"4px 12px",fontSize:11,fontWeight:600,color:"#059669",background:"#d1fae5",border:"1px solid #a7f3d0",borderRadius:6,cursor:"pointer",fontFamily:F}}>Valida</button>}{!readOnly&&p2<100&&<span style={{fontSize:10,color:"#94a3b8",fontStyle:"italic"}}>Completare prima</span>}{readOnly&&<span style={{fontSize:10,color:"#94a3b8"}}>—</span>}</div>}</td></tr>);})}</tbody>
        </table>
      </div>
      {/* SECTION CARDS */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:12}}>
        {SECTIONS.map((s,idx)=>{const d=sDone(s),t=sTotal(s),na=sNA(s),sp=t>0?Math.round((d/t)*100):0;const mc=MACROS.find(m=>m.id===s.macro);const v=validations[s.macro];
          const hasFilterMatch=dashFilter==="all"||s.fields.some(f=>fieldMatchesFilter(f));
          if(!hasFilterMatch)return null;
          return(
          <div key={s.id} onClick={()=>{goToSection(idx);setPanel(null);}} style={{...C({padding:"14px 16px",cursor:"pointer",textAlign:"left",position:"relative",overflow:"hidden",transition:"transform .15s",border:v?"2px solid #a7f3d0":"1px solid #e2e8f0"}),fontFamily:F}}>
            <div style={{position:"absolute",top:0,left:0,right:0,height:3,background:sp===100?"#10b981":mc.color,opacity:sp>0?1:.12}}/>
            <div style={{display:"flex",justifyContent:"space-between",marginBottom:4}}><span style={{fontSize:10,fontWeight:700,color:mc.color,letterSpacing:.5}}>{mc.label}</span><span style={{fontSize:10,fontWeight:700,color:sp===100?"#059669":sp>0?mc.color:"#94a3b8"}}>{d}/{t}{na>0&&<span style={{color:"#ef4444",marginLeft:4}}>({na} N/A)</span>}</span></div>
            <div style={{fontSize:12.5,fontWeight:700,color:"#0f172a",marginBottom:8}}>{s.title}</div>
            <div style={{height:4,background:"#f1f5f9",borderRadius:99}}><div style={{height:"100%",width:sp+"%",background:sp===100?"#10b981":mc.color,borderRadius:99,transition:"width .3s"}}/></div>
            {v&&<div style={{marginTop:6,fontSize:9,color:"#059669",fontWeight:600}}>Macro area validata</div>}
          </div>);})}
      </div></div>);
  };

  /* ============ SECTION FORM VIEW ============ */
  const SecView=()=>{
    const idx=view;const s=SECTIONS[idx];const mc=MACROS.find(m=>m.id===s.macro);const na=sNA(s);
    const v=validations[s.macro];
    const visibleFields=s.fields.filter(f=>fieldMatchesFilter(f));
    const allFields=s.fields;
    const showingFiltered=dashFilter!=="all";
    return(<div>
      {readOnly&&<div style={{padding:"10px 16px",background:"#fef3c7",borderRadius:10,marginBottom:14,fontSize:12,fontWeight:600,color:"#92400e",fontFamily:F}}>Sola lettura — Ambiente esclusivo del cliente</div>}
      {v&&<div style={{padding:"10px 16px",background:"#d1fae5",borderRadius:10,marginBottom:14,fontSize:12,fontWeight:600,color:"#065f46",fontFamily:F}}>Macro area validata da {v.by} il {v.at}</div>}
      <div style={C({overflow:"hidden"})}>
        <div style={{padding:"22px 26px 18px",borderBottom:"1px solid #f1f5f9",background:mc?.bg+"40"}}>
          <div style={{display:"flex",alignItems:"center",gap:12,marginBottom:8}}>
            <span style={{display:"inline-block",padding:"3px 12px",fontSize:10,fontWeight:700,color:mc?.color,background:mc?.bg,borderRadius:8,letterSpacing:.5,fontFamily:F}}>{mc?.label}</span>
            {na>0&&<span style={{padding:"3px 10px",fontSize:10,fontWeight:700,color:"#ef4444",background:"#fef2f2",borderRadius:8}}>{na} N/A</span>}
            {showingFiltered&&<span style={{padding:"3px 10px",fontSize:10,fontWeight:600,color:"#6366f1",background:"#eef2ff",borderRadius:8}}>{visibleFields.length}/{allFields.length} campi</span>}
          </div>
          <h2 style={{margin:0,fontSize:22,fontWeight:800,color:"#0f172a",fontFamily:F}}>{s.title}</h2>
        </div>
        <div style={{padding:"22px 26px 8px"}}>{(showingFiltered?visibleFields:allFields).map(f=><Field key={f.id} field={f} value={data[f.id]} onChange={handleChange} fieldNote={fieldNotes[f.id]} onNoteChange={handleFN} naChecked={!!naFields[f.id]} onNaChange={handleNA} readOnly={readOnly} adminNote={adminNotes[f.id]} onAdminNoteChange={handleAN} isAdmin={isAdmin}/>)}
          {showingFiltered&&visibleFields.length===0&&<div style={{textAlign:"center",padding:40,color:"#94a3b8",fontSize:13,fontFamily:F}}>Nessun campo corrisponde al filtro selezionato in questa sezione.</div>}
        </div>
        {!readOnly&&<div style={{padding:"0 26px 22px"}}><div style={{padding:"14px 16px",background:"#fefce8",borderRadius:12,border:"1.5px solid #fef08a"}}><label style={{display:"block",fontSize:11,fontWeight:700,color:"#854d0e",marginBottom:6,fontFamily:F,letterSpacing:.3}}>NOTE E OSSERVAZIONI SULLA SEZIONE</label><textarea value={sectionNotes[s.id]||""} onChange={e=>handleSN(s.id,e.target.value)} rows={2} placeholder="Annotazioni sulla sezione..." style={{width:"100%",padding:"8px 12px",fontSize:12.5,border:"1.5px solid #fef08a",borderRadius:8,background:"#fefdf5",color:"#713f12",fontFamily:F,outline:"none",resize:"vertical",boxSizing:"border-box"}}/></div></div>}
        {readOnly&&sectionNotes[s.id]&&<div style={{padding:"0 26px 22px"}}><div style={{padding:"10px 14px",background:"#fefce8",borderRadius:10,border:"1px solid #fef08a",fontSize:12.5,color:"#713f12",fontFamily:F}}>Note sezione: {sectionNotes[s.id]}</div></div>}
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"14px 26px",borderTop:"1px solid #f1f5f9",background:"#fafbfc"}}>
          <button onClick={()=>idx>0?goToSection(idx-1):goToSection("dashboard")} style={S("#fff","#334155",{border:"1.5px solid #e2e8f0"})}>{idx>0?"Precedente":"Dashboard"}</button>
          <span style={{fontSize:12,color:"#94a3b8",fontFamily:F,fontWeight:600}}>{idx+1}/{SECTIONS.length}</span>
          <button onClick={()=>idx<SECTIONS.length-1?goToSection(idx+1):goToSection("dashboard")} style={S("linear-gradient(135deg,#6366f1,#8b5cf6)","#fff")}>{idx<SECTIONS.length-1?"Successiva":"Dashboard"}</button>
        </div>
      </div></div>);
  };

  /* ============ MAIN LAYOUT ============ */
  return(<div style={{fontFamily:F,display:"flex",height:"100vh",overflow:"hidden",background:"#f0f2f7"}}>
    <aside style={{width:sidebarOpen?290:0,minWidth:sidebarOpen?290:0,background:"linear-gradient(180deg,#0c1222,#1a1f3a)",display:"flex",flexDirection:"column",transition:"all .3s",overflow:"hidden",flexShrink:0}}>
      <div style={{padding:"20px 18px 16px",display:"flex",alignItems:"center",justifyContent:"space-between",borderBottom:"1px solid rgba(255,255,255,.06)"}}>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <div style={{width:38,height:38,borderRadius:12,background:"linear-gradient(135deg,#6366f1,#8b5cf6)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:17,fontWeight:900,color:"#fff",fontFamily:F,boxShadow:"0 4px 12px rgba(99,102,241,.3)"}}>G</div>
          <div><div style={{fontSize:14,fontWeight:800,color:"#fff",fontFamily:F}}>GOVERNANCE</div><div style={{fontSize:9,color:"#a5b4fc",fontWeight:700,letterSpacing:2,textTransform:"uppercase",fontFamily:F}}>Pre-Assessment v13</div></div>
        </div>
      </div>
      <div style={{padding:"12px 18px",borderBottom:"1px solid rgba(255,255,255,.06)"}}>
        <div style={{fontSize:13,fontWeight:700,color:"#fff",fontFamily:F}}>{auth.name}</div>
        <div style={{fontSize:10,color:"#94a3b8",fontFamily:F}}>{auth.role==="admin"?"Consulente":"Cliente"}</div>
      </div>
      {auth.role==="admin"&&<div style={{padding:"10px 14px",borderBottom:"1px solid rgba(255,255,255,.06)"}}>
        <div style={{fontSize:10,fontWeight:700,color:"#a5b4fc",textTransform:"uppercase",letterSpacing:1,marginBottom:6,fontFamily:F}}>Clienti</div>
        {myUsers.map(u=>(<button key={u.id} onClick={()=>{setSelectedUser(u.id);setView("dashboard");setPanel(null);setDashFilter("all");}} style={{display:"flex",alignItems:"center",gap:8,width:"100%",padding:"8px 10px",border:"none",borderRadius:8,background:selectedUser===u.id?"rgba(99,102,241,.15)":"transparent",cursor:"pointer",fontFamily:F,marginBottom:2}}>
          <span style={{fontSize:12,fontWeight:selectedUser===u.id?700:400,color:selectedUser===u.id?"#fff":"rgba(255,255,255,.7)"}}>{u.name}</span>
        </button>))}
        <button onClick={()=>{if(myUsers.length<(admins.find(a=>a.id===auth.id)?.maxSub||0)){const nid=uid();setUsers(p=>[...p,{id:nid,adminId:auth.id,name:"Nuovo Cliente",email:"",active:true}]);setAssessments(p=>({...p,[nid]:{...initData}}));}}} style={{display:"flex",alignItems:"center",gap:6,width:"100%",padding:"7px 10px",border:"1px dashed rgba(255,255,255,.15)",borderRadius:8,background:"transparent",cursor:"pointer",fontFamily:F,color:"#64748b",fontSize:11,marginTop:4}}>+ Nuovo cliente</button>
      </div>}
      <div style={{padding:"8px 12px 4px"}}>
        <button onClick={()=>{setView("dashboard");setPanel(null);}} style={{display:"flex",alignItems:"center",gap:10,width:"100%",padding:"9px 14px",border:"none",borderRadius:10,background:view==="dashboard"&&!panel?"rgba(99,102,241,.15)":"transparent",cursor:"pointer",fontFamily:F}}>
          <span style={{fontSize:13,fontWeight:view==="dashboard"&&!panel?700:500,color:view==="dashboard"&&!panel?"#fff":"#94a3b8"}}>Dashboard</span>
        </button>
        {showAss&&[["chat","Chat"],["tickets","Ticket"],["alerts","Alert"]].map(([p,l])=>(<button key={p} onClick={()=>setPanel(panel===p?null:p)} style={{display:"flex",alignItems:"center",gap:10,width:"100%",padding:"9px 14px",border:"none",borderRadius:10,background:panel===p?"rgba(99,102,241,.15)":"transparent",cursor:"pointer",fontFamily:F}}>
          <span style={{fontSize:13,fontWeight:panel===p?700:500,color:panel===p?"#fff":"#94a3b8"}}>{l}</span>
        </button>))}
      </div>
      {showAss&&!panel&&<>
        <div style={{padding:"6px 14px 2px"}}><input type="text" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Cerca sezione o campo..." style={{width:"100%",padding:"8px 12px",fontSize:12,border:"1px solid rgba(255,255,255,.08)",borderRadius:9,background:"rgba(255,255,255,.05)",color:"#e2e8f0",fontFamily:F,outline:"none",boxSizing:"border-box"}}/></div>
        <nav style={{flex:1,overflowY:"auto",padding:"2px 0 8px"}}>
          {grouped.map(g=>{const isOpen=expandedMacro===g.id;const gd=g.sections.reduce((a,s)=>a+sDone(s),0);const gt=g.sections.reduce((a,s)=>a+sTotal(s),0);const gp=gt>0?Math.round((gd/gt)*100):0;return(<div key={g.id}>
            <button onClick={()=>setExpandedMacro(isOpen?null:g.id)} style={{display:"flex",alignItems:"center",gap:8,width:"100%",padding:"10px 18px",border:"none",background:isOpen?"rgba(255,255,255,.06)":"none",cursor:"pointer",fontFamily:F,transition:"background .15s"}}>
              <span style={{fontSize:11,fontWeight:700,color:"#fff",letterSpacing:.3,flex:1,textAlign:"left"}}>{g.id.toUpperCase()}. {g.label}</span>
              {validations[g.id]&&<span style={{width:6,height:6,borderRadius:99,background:"#10b981"}}/>}
              <span style={{fontSize:9,fontWeight:700,color:gp===100?"#10b981":gp>0?"#a5b4fc":"#475569",minWidth:28,textAlign:"right"}}>{gp}%</span>
              <span style={{color:"#475569",fontSize:8,transition:"transform .2s",transform:isOpen?"rotate(180deg)":"rotate(0deg)"}}>&#9660;</span>
            </button>
            {isOpen&&g.sections.map(s=>{const idx=SECTIONS.indexOf(s);const isA=view===idx&&!panel;const d=sDone(s),t=sTotal(s),na=sNA(s);return(
              <button key={s.id} onClick={()=>{goToSection(idx);setPanel(null);}} style={{display:"flex",alignItems:"center",gap:6,width:"100%",padding:"7px 16px 7px 28px",border:"none",background:isA?"rgba(99,102,241,.12)":"transparent",borderLeft:isA?"3px solid "+g.color:"3px solid transparent",cursor:"pointer",fontFamily:F}}>
                <span style={{fontSize:11.5,fontWeight:isA?700:400,color:isA?"#fff":"rgba(255,255,255,.7)",flex:1,textAlign:"left",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{s.title}</span>
                {na>0&&<span style={{fontSize:9,fontWeight:700,color:"#fca5a5",background:"rgba(239,68,68,.15)",padding:"1px 5px",borderRadius:4}}>{na}</span>}
                <span style={{fontSize:10,fontWeight:700,color:t>0&&d===t?"#10b981":d>0?"#a5b4fc":"#475569"}}>{d}/{t}</span>
              </button>);})}
          </div>);})}
        </nav>
      </>}
      {showAss&&!panel&&<div style={{padding:"10px 16px",borderTop:"1px solid rgba(255,255,255,.06)"}}>
        <button onClick={()=>setShowExport(!showExport)} style={{display:"flex",alignItems:"center",gap:6,width:"100%",justifyContent:"center",padding:"8px 12px",fontSize:12,fontWeight:600,color:"#e2e8f0",background:"rgba(255,255,255,.06)",border:"1px solid rgba(255,255,255,.08)",borderRadius:8,cursor:"pointer",fontFamily:F}}>Esporta</button>
        {showExport&&<div style={{marginTop:8}}>
          <div style={{display:"flex",gap:4,marginBottom:6,background:"rgba(255,255,255,.04)",borderRadius:7,padding:3}}>
            {[["all","TUTTO"],["excludeNA","ESCLUDI N/A"]].map(([k,l])=>(<button key={k} onClick={()=>setExportMode(k)} style={{flex:1,padding:"6px 8px",fontSize:10,fontWeight:700,color:exportMode===k?"#fff":k==="excludeNA"?"#fca5a5":"#94a3b8",background:exportMode===k?(k==="excludeNA"?"rgba(239,68,68,.3)":"rgba(99,102,241,.25)"):"transparent",border:"none",borderRadius:5,cursor:"pointer",fontFamily:F,letterSpacing:.5,transition:"all .15s"}}>{l}</button>))}
          </div>
          <label style={{display:"flex",alignItems:"center",gap:6,padding:"5px 8px",marginBottom:8,cursor:"pointer",userSelect:"none"}}><input type="checkbox" checked={exportAdminNotes} onChange={e=>setExportAdminNotes(e.target.checked)} style={{width:13,height:13,accentColor:"#f59e0b"}}/><span style={{fontSize:10,fontWeight:600,color:exportAdminNotes?"#fde68a":"#64748b",fontFamily:F,letterSpacing:.3}}>INCLUDI NOTE CONSULENTE</span></label>
          <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
            <button onClick={exportJSON} style={{flex:1,padding:"7px",fontSize:11,fontWeight:600,color:"#c7d2fe",background:"rgba(99,102,241,.15)",border:"1px solid rgba(99,102,241,.2)",borderRadius:7,cursor:"pointer",fontFamily:F}}>JSON</button>
            <button onClick={exportCSV} style={{flex:1,padding:"7px",fontSize:11,fontWeight:600,color:"#c7d2fe",background:"rgba(99,102,241,.15)",border:"1px solid rgba(99,102,241,.2)",borderRadius:7,cursor:"pointer",fontFamily:F}}>CSV</button>
            <button onClick={()=>genPDF(data,sectionNotes,fieldNotes,naFields,adminNotes,exportMode,exportAdminNotes)} style={{flex:"1 1 100%",padding:"8px",fontSize:11,fontWeight:600,color:"#fecaca",background:"rgba(239,68,68,.12)",border:"1px solid rgba(239,68,68,.2)",borderRadius:7,cursor:"pointer",fontFamily:F}}>Report PDF</button>
          </div>
        </div>}
      </div>}
      <div style={{padding:"8px 18px 14px",display:"flex",alignItems:"center",justifyContent:"space-between"}}>
        <span style={{fontSize:10,color:"#475569",fontFamily:F}}>v13.0</span>
        <button onClick={()=>setAuth(null)} style={{display:"flex",alignItems:"center",gap:4,padding:"5px 10px",fontSize:11,color:"#94a3b8",background:"none",border:"1px solid rgba(255,255,255,.08)",borderRadius:6,cursor:"pointer",fontFamily:F}}>Esci</button>
      </div>
    </aside>
    <div style={{flex:1,display:"flex",flexDirection:"column",overflow:"hidden"}}>
      <header style={{height:54,background:"#fff",borderBottom:"1px solid #e8ecf1",display:"flex",alignItems:"center",padding:"0 22px",gap:12,flexShrink:0}}>
        {!sidebarOpen&&<button onClick={()=>setSidebarOpen(true)} style={{background:"none",border:"none",color:"#64748b",cursor:"pointer",padding:4,fontSize:14,fontFamily:F}}>Menu</button>}
        <div style={{display:"flex",alignItems:"center",gap:6,fontSize:12,color:"#94a3b8",fontFamily:F}}>
          <span style={{cursor:"pointer"}} onClick={()=>{setView("dashboard");setPanel(null);}}>Pre-Assessment v13</span>
          {panel&&<><span>/</span><span style={{color:"#334155",fontWeight:600}}>{panel==="chat"?"Chat":panel==="tickets"?"Ticket":"Alert"}</span></>}
          {!panel&&activeSection&&<><span>/</span><span style={{color:activeMacro?.color,fontWeight:600}}>{activeMacro?.label}</span><span>/</span><span style={{color:"#334155",fontWeight:600}}>{activeSection.title}</span></>}
          {!panel&&!activeSection&&<><span>/</span><span style={{color:"#334155",fontWeight:600}}>Dashboard</span></>}
        </div>
        <div style={{flex:1}}/>
        {dashFilter!=="all"&&<span style={{...B(dashFilter==="na"?"#ef4444":"#6366f1",dashFilter==="na"?"#fef2f2":"#eef2ff"),fontSize:10}}>Filtro: {dashFilter==="completed"?"Completati":dashFilter==="todo"?"Da completare":"N/A"}</span>}
        <span style={{fontSize:12,fontWeight:600,color:"#334155",fontFamily:F}}>{auth.name}</span>
        <div style={{width:34,height:34,borderRadius:99,background:"linear-gradient(135deg,#6366f1,#8b5cf6)",display:"flex",alignItems:"center",justifyContent:"center",color:"#fff",fontSize:12,fontWeight:700,fontFamily:F}}>{auth.name.charAt(0)}</div>
      </header>
      <main style={{flex:1,overflowY:"auto",padding:panel?0:22}}>
        {panel==="chat"&&showAss&&<ChatPanel messages={getChats(actUid)} onSend={sendChat} myId={curId} other={otherName}/>}
        {panel==="tickets"&&showAss&&<TicketPanel tickets={getTickets(actUid)} onNew={createTicket} onReply={replyTicket} myId={curId} isAdmin={auth.role==="admin"}/>}
        {panel==="alerts"&&showAss&&<AlertPanel alerts={getAlerts(actUid)} onNew={createAlert} users={myUsers} isAdmin={auth.role==="admin"}/>}
        {!panel&&(view==="dashboard"?<DashView/>:typeof view==="number"&&showAss?<SecView/>:<DashView/>)}
      </main>
    </div>
  </div>);
}
